using UnityEngine;
using UnityEditor;
using System.Linq;
using ConRoi.Investigation.V36;

namespace Unity.AI.Assistant.Agent.Dynamic.Extension.Editor
{
    internal class CommandScript : IRunCommand
    {
        public void Execute(ExecutionResult r)
        {
            foreach (var s in Object.FindObjectsByType<InvestigationSession>(FindObjectsSortMode.None))
                r.Log("session " + s.name + " scene=" + s.gameObject.scene.path);
            foreach (var i in Object.FindObjectsByType<InvestigationInteractable>(FindObjectsSortMode.None))
            {
                r.Log(i.name + " id=" + i.evidenceId + " childrenColliders=" + string.Join(",", i.GetComponentsInChildren<Collider>().Select(c => c.GetType().Name + " " + c.bounds)) + " mesh=" + string.Join(",", i.GetComponentsInChildren<Renderer>().Select(c => c.GetType().Name + " " + c.bounds)));
            }
        }
    }
}

